SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS unit;
CREATE TABLE unit (
  id_unit         INT            NOT NULL AUTO_INCREMENT,
  nama_sentral    VARCHAR(120)   NOT NULL COMMENT 'Nama sentral (col6)',
  nama_rayon      VARCHAR(120)       NULL COMMENT 'Nama unit/rayon (col5)',
  unit_pelaksana  VARCHAR(80)        NULL COMMENT 'Unit pelaksana (col4)',
  milik           VARCHAR(20)        NULL COMMENT 'Pemilik aset (col3)',
  PRIMARY KEY (id_unit),
  UNIQUE KEY uq_sentral (nama_sentral)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Master unit sentral pembangkit';

