DROP TABLE IF EXISTS mesin;
CREATE TABLE mesin (
  id_mesin              INT            NOT NULL AUTO_INCREMENT,
  no_urut               TINYINT UNSIGNED NOT NULL         COMMENT 'Nomor urut (col2)',
  id_unit               INT            NOT NULL           COMMENT 'FK -> unit.id_unit',
  nama_mesin            VARCHAR(200)       NULL           COMMENT 'Nama/label mesin (col7)',
  sistim                VARCHAR(80)        NULL           COMMENT 'Sistem jaringan (col8)',
  pgk_merk              VARCHAR(120)       NULL           COMMENT 'Merk penggerak (col9)',
  pgk_type              VARCHAR(100)       NULL           COMMENT 'Type penggerak (col10)',
  pgk_seri              VARCHAR(100)       NULL           COMMENT 'Seri penggerak (col11)',
  tahun_operasi         SMALLINT UNSIGNED  NULL           COMMENT 'Tahun operasi (col12)',
  gen_merk              VARCHAR(120)       NULL           COMMENT 'Merk generator (col13)',
  gen_tipe              VARCHAR(100)       NULL           COMMENT 'Tipe generator (col14)',
  gen_seri              VARCHAR(100)       NULL           COMMENT 'Seri generator (col15)',
  gen_tegangan_output   INT UNSIGNED       NULL           COMMENT 'Tegangan output V (col16)',
  trafo_nama            VARCHAR(200)       NULL           COMMENT 'Nama trafo (col17)',
  trafo_merk            VARCHAR(120)       NULL           COMMENT 'Merk trafo (col18)',
  trafo_seri            VARCHAR(100)       NULL           COMMENT 'Seri trafo (col19)',
  trafo_tegangan_hvlv   VARCHAR(20)        NULL           COMMENT 'Tegangan HV/LV kV (col20)',
  trafo_kapasitas_kva   SMALLINT UNSIGNED  NULL           COMMENT 'Kapasitas KVA (col21)',
  jenis_pembangkit      VARCHAR(10)        NULL           COMMENT 'PLTD/PLTM dll (col22)',
  status                VARCHAR(50)        NULL           COMMENT 'Status operasi (col23)',
  jenis_bahan_bakar     VARCHAR(30)        NULL           COMMENT 'Jenis BBM (col24)',
  status_tegangan       VARCHAR(10)        NULL           COMMENT 'TM/TR dll (col25)',
  beban_puncak_kw       INT UNSIGNED       NULL           COMMENT 'Beban puncak/NDC KW (col26)',
  daya_terpasang_kw     DECIMAL(8,1)       NULL           COMMENT 'Daya terpasang KW (col27)',
  dmn_kw                INT UNSIGNED       NULL           COMMENT 'DMN KW (col28)',
  kota_kabupaten        VARCHAR(60)        NULL           COMMENT 'Kota/kabupaten (col29)',
  porsi_neraca_energi   VARCHAR(20)        NULL           COMMENT 'Porsi neraca energi (col30)',
  PRIMARY KEY (id_mesin),
  KEY idx_unit (id_unit),
  KEY idx_sentral (id_unit, no_urut),
  CONSTRAINT fk_mesin_unit FOREIGN KEY (id_unit)
    REFERENCES unit (id_unit)
    ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Data mesin pembangkit listrik UPDK Kendari';

